{
  "decision-reserve-a-weather-resilient-pick-plan": "WITH chosen AS (SELECT plan_code, MIN(sale_cartons) AS guaranteed_cartons FROM field_trial GROUP BY plan_code COLLATE BINARY HAVING MAX(bulk_bins) <= (SELECT vacant_spaces FROM cool_room) ORDER BY guaranteed_cartons DESC, plan_code COLLATE BINARY ASC LIMIT 1) SELECT c.plan_code, c.guaranteed_cartons, t.trial_id FROM chosen AS c JOIN field_trial AS t ON t.plan_code COLLATE BINARY = c.plan_code AND t.sale_cartons = c.guaranteed_cartons ORDER BY t.trial_id COLLATE BINARY ASC LIMIT 1",
  "decision-reserve-an-unbroken-charging-window": "WITH pairs AS (SELECT a.start_min, d.initial_kwh + a.delivery_kwh + b.delivery_kwh AS final_kwh, a.price_cents + b.price_cents AS cost_cents, d.source_id, d.required_kwh, d.capacity_kwh FROM charger_slot AS a JOIN charger_slot AS b ON b.start_min = a.start_min + 10 CROSS JOIN duty_card AS d WHERE a.start_min >= 0 AND b.start_min + 10 <= d.pullout_min AND a.delivery_kwh IS NOT NULL AND b.delivery_kwh IS NOT NULL AND a.price_cents IS NOT NULL AND b.price_cents IS NOT NULL) SELECT start_min, final_kwh, cost_cents, source_id FROM pairs WHERE final_kwh BETWEEN required_kwh AND capacity_kwh ORDER BY cost_cents ASC, start_min ASC LIMIT 1",
  "decision-reserve-folio-stock-before-demand-is-known": "SELECT m.memo_id, o.offer_id, o.lot_sheets AS staged_sheets, 100 * o.fee_cents + (SELECT SUM(d.weight_pct * (MAX(d.need_sheets - o.lot_sheets, 0) * m.rush_cents - MAX(o.lot_sheets - d.need_sheets, 0) * m.pulp_cents)) FROM demand_outcome AS d) AS cost_hundredths_cent FROM folio_offer AS o CROSS JOIN press_memo AS m WHERE o.lot_sheets <= m.stage_cap ORDER BY cost_hundredths_cent ASC, staged_sheets ASC, o.offer_id COLLATE BINARY ASC LIMIT 1",
  "decision-reserve-proof-press-slot": "WITH eligible AS (SELECT batch_code, ink_code, run_min, service_points FROM proof_queue WHERE run_min IS NOT NULL), bookings AS (SELECT batch_code AS first_batch, NULL AS second_batch, service_points AS total_points, run_min AS occupied_min FROM eligible UNION ALL SELECT a.batch_code, b.batch_code, a.service_points + b.service_points, a.run_min + b.run_min + CASE WHEN a.ink_code COLLATE BINARY <> b.ink_code THEN 3 ELSE 0 END FROM eligible AS a JOIN eligible AS b ON a.batch_code COLLATE BINARY < b.batch_code) SELECT first_batch, second_batch, total_points, occupied_min FROM bookings WHERE occupied_min <= 12 ORDER BY total_points DESC, occupied_min ASC, first_batch COLLATE BINARY ASC, second_batch COLLATE BINARY ASC LIMIT 1"
}
